export type VnAdministrativeRegionType = 'BAC_BO' | 'TRUNG_BO' | 'TAY_NGUYEN' | 'NAM_BO';

export type VnHamletUnitType =
  | 'THON'
  | 'AP'
  | 'BAN'
  | 'LANG'
  | 'KHU_PHO'
  | 'TO_DAN_PHO'
  | 'KHOM'
  | 'TIEU_KHU'
  | 'XOM'
  | 'KHU_DO_THI'
  | 'DUONG_PHO';

export interface VnHamletUnitItem {
  code: string;
  name: string;
  unitType: VnHamletUnitType;
  aliases: string[];
  ghtkHamletName: string;
}

export interface VnWardUnitItem {
  code: string;
  name: string;
  unitType?: 'PHUONG' | 'XA' | 'THI_TRAN' | 'DAC_KHU';
  aliases: string[];
  ghnWardCode: string;
  ghtkWardName: string;
  hamlets?: VnHamletUnitItem[];
}

export interface VnDistrictUnitItem {
  code: string;
  name: string;
  unitType?: 'QUAN' | 'HUYEN' | 'THI_XA' | 'THANH_PHO' | 'DAC_KHU';
  aliases: string[];
  ghnDistrictId: number;
  ghtkDistrictName: string;
  wards: VnWardUnitItem[];
}

export interface VnProvinceUnitItem {
  code: string;
  name: string;
  region?: VnAdministrativeRegionType;
  aliases: string[];
  ghnProvinceId: number;
  ghtkProvinceName: string;
  vtpProvinceId: number;
  jtCityCode: string;
  isCurrent34Province?: boolean;
  mergedIntoProvinceCode?: string;
  mergedIntoProvinceName?: string;
  mergedFromProvinceCodes?: string[];
  mergedFromProvinceNames?: string[];
  districts: VnDistrictUnitItem[];
}

export type IVnHamletUnit = VnHamletUnitItem;
export type IVnWardUnit = VnWardUnitItem;
export type IVnDistrictUnit = VnDistrictUnitItem;
export type IVnProvinceUnit = VnProvinceUnitItem;

interface CompactWardSeed {
  c: string;
  n: string;
  g: string;
  a?: string[];
}

interface CompactDistrictSeed {
  c: string;
  n: string;
  g: number;
  w: CompactWardSeed[];
}

interface CompactProvinceSeed {
  c: string;
  n: string;
  r: VnAdministrativeRegionType;
  a: string[];
  gp: number;
  gk: string;
  vp: number;
  jt: string;
  c34: boolean;
  mc: string;
  mn: string;
  mfc: string[];
  mfn: string[];
  d: CompactDistrictSeed[];
}

function stripVnAccents(input: string): string {
  return input
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/gi, 'd')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function stripUnitPrefix(name: string): string {
  return name
    .replace(/^(Thành phố|Tỉnh|Quận|Huyện đảo|Huyện|Thị xã|Phường|Xã|Thị trấn|Đặc khu)\s+/i, '')
    .replace(/\s*\([^)]*\)\s*/g, '')
    .trim();
}

function buildProvinceAliases(name: string, extra: string[]): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const isCity = /^Thành phố/i.test(name);
  const set = new Set<string>([
    short,
    full,
    isCity ? `tp ${short}` : `tinh ${short}`,
    short.replace(/\s+/g, ''),
  ]);
  for (const ex of extra) {
    const clean = stripVnAccents(ex);
    if (clean) set.add(clean);
  }
  return Array.from(set);
}

function buildDistrictAliases(name: string): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const set = new Set<string>([full, short]);
  if (/^Quận\s+/i.test(name)) {
    set.add(`q ${short}`);
    set.add(`q.${short}`);
    if (/^\d+$/.test(short)) set.add(`q${short}`);
  } else if (/^Huyện/i.test(name)) {
    set.add(`h ${short}`);
    set.add(`huyen ${short}`);
  } else if (/^Thị xã/i.test(name)) {
    set.add(`tx ${short}`);
    set.add(`thi xa ${short}`);
  } else if (/^Thành phố/i.test(name)) {
    set.add(`tp ${short}`);
    set.add(`tp.${short}`);
  } else if (/^Đặc khu/i.test(name)) {
    set.add(`dac khu ${short}`);
    set.add(`huyen dao ${short}`);
  }
  return Array.from(set);
}

function buildWardAliases(name: string, extra?: string[]): string[] {
  const short = stripVnAccents(stripUnitPrefix(name));
  const full = stripVnAccents(name.replace(/\s*\([^)]*\)\s*/g, ''));
  const set = new Set<string>([full, short]);
  if (/^Phường\s+/i.test(name)) {
    set.add(`p ${short}`);
    set.add(`p.${short}`);
    if (/^\d+$/.test(short)) set.add(`p${short}`);
  } else if (/^Xã\s+/i.test(name)) {
    set.add(`x ${short}`);
    set.add(`xa ${short}`);
  } else if (/^Thị trấn\s+/i.test(name)) {
    set.add(`tt ${short}`);
    set.add(`thi tran ${short}`);
  } else if (/^Đặc khu\s+/i.test(name)) {
    set.add(`dac khu ${short}`);
  }
  if (extra) {
    for (const ex of extra) {
      const clean = stripVnAccents(ex);
      if (clean) set.add(clean);
    }
  }
  return Array.from(set);
}

function buildFourthTierHamlets(
  wardCode: string,
  wardName: string,
  region: VnAdministrativeRegionType,
  extraStreets?: string[],
): VnHamletUnitItem[] {
  const isUrban = /^(Phường|Thị trấn|Đặc khu)\s+/i.test(wardName);
  const hamlets: VnHamletUnitItem[] = [];

  const presets: Array<[string, VnHamletUnitType, string[]]> = isUrban
    ? region === 'NAM_BO'
      ? [
          ['Khu phố 1', 'KHU_PHO', ['kp 1', 'kp1', 'khu pho 1']],
          ['Khu phố 2', 'KHU_PHO', ['kp 2', 'kp2', 'khu pho 2']],
          ['Khu phố 3', 'KHU_PHO', ['kp 3', 'kp3', 'khu pho 3']],
          ['Khu phố 4', 'KHU_PHO', ['kp 4', 'kp4', 'khu pho 4']],
          ['Khu phố 5', 'KHU_PHO', ['kp 5', 'kp5', 'khu pho 5']],
          ['Khóm 1', 'KHOM', ['khom 1']],
          ['Khóm 2', 'KHOM', ['khom 2']],
          ['Tổ dân phố 1', 'TO_DAN_PHO', ['tdp 1', 'to 1', 'to dan pho 1']],
        ]
      : [
          ['Tổ dân phố số 1', 'TO_DAN_PHO', ['tdp 1', 'tdp so 1', 'to 1', 'to dan pho 1']],
          ['Tổ dân phố số 2', 'TO_DAN_PHO', ['tdp 2', 'tdp so 2', 'to 2', 'to dan pho 2']],
          ['Tổ dân phố số 3', 'TO_DAN_PHO', ['tdp 3', 'tdp so 3', 'to 3', 'to dan pho 3']],
          ['Tổ dân phố số 4', 'TO_DAN_PHO', ['tdp 4', 'tdp so 4', 'to 4', 'to dan pho 4']],
          ['Tổ dân phố số 5', 'TO_DAN_PHO', ['tdp 5', 'tdp so 5', 'to 5', 'to dan pho 5']],
          ['Khu phố 1', 'KHU_PHO', ['kp 1', 'kp1', 'khu pho 1']],
          ['Khu phố 2', 'KHU_PHO', ['kp 2', 'kp2', 'khu pho 2']],
          ['Tiểu khu 1', 'TIEU_KHU', ['tieu khu 1', 'tk 1']],
        ]
    : region === 'NAM_BO'
      ? [
          ['Ấp 1', 'AP', ['ap 1', 'ap 1a']],
          ['Ấp 2', 'AP', ['ap 2', 'ap trung tam']],
          ['Ấp 3', 'AP', ['ap 3']],
          ['Ấp 4', 'AP', ['ap 4']],
          ['Ấp Bình Hòa', 'AP', ['ap binh hoa', 'ap my hoa']],
          ['Khóm 1', 'KHOM', ['khom 1']],
        ]
      : region === 'TAY_NGUYEN'
        ? [
            ['Thôn 1', 'THON', ['thon 1', 'buon 1']],
            ['Thôn 2', 'THON', ['thon 2', 'buon 2']],
            ['Thôn 3', 'THON', ['thon 3', 'buon 3']],
            ['Bản 1', 'BAN', ['ban 1', 'plei 1']],
            ['Tổ dân phố 1', 'TO_DAN_PHO', ['tdp 1', 'to 1']],
          ]
        : [
            ['Thôn 1', 'THON', ['thon 1', 'xom 1']],
            ['Thôn 2', 'THON', ['thon 2', 'xom 2']],
            ['Thôn 3', 'THON', ['thon 3', 'xom 3']],
            ['Thôn Trung Tâm', 'THON', ['thon trung tam', 'xom trung tam']],
            ['Bản 1', 'BAN', ['ban 1']],
            ['Tổ dân phố số 1', 'TO_DAN_PHO', ['tdp 1', 'to 1']],
          ];

  presets.forEach(([hName, hType, hAliases], idx) => {
    hamlets.push({
      code: `${wardCode}-H${idx + 1}`,
      name: hName,
      unitType: hType,
      aliases: hAliases,
      ghtkHamletName: hName,
    });
  });

  if (extraStreets && extraStreets.length > 0) {
    extraStreets.slice(0, 3).forEach((st, idx) => {
      const isKdt = /vinhomes|city|park|kdt|chung cu|aeon|ciputra|ecopark|vsip/i.test(st);
      const label = isKdt ? `KĐT ${st}` : `Đường ${st}`;
      hamlets.push({
        code: `${wardCode}-S${idx + 1}`,
        name: label,
        unitType: isKdt ? 'KHU_DO_THI' : 'DUONG_PHO',
        aliases: [stripVnAccents(st), stripVnAccents(label)],
        ghtkHamletName: label,
      });
    });
  }

  return hamlets;
}

