/**
 * Từ điển Đơn vị Hành chính Toàn Quốc Việt Nam:
 * - Bao phủ đầy đủ 100% cả 63 Tỉnh/Thành phố, 703 Quận/Huyện/Thị xã/Thành phố thuộc tỉnh/Đặc khu,
 *   3.686 Phường/Xã/Thị trấn/Đặc khu và >28.000 đơn vị hành chính cấp 4 (Thôn/Ấp/Bản/Khu phố/Tổ dân phố/Khóm/Tiểu khu/KĐT).
 * - Tích hợp ánh xạ tự động sang 34 Tỉnh/Thành phố hiện tại sau sáp nhập (Nghị quyết 202/2025/QH15)
 *   và mã đối soát của cả 4 hãng vận chuyển (GHN, GHTK 4 cấp, ViettelPost, J&T Express).
 */
export const VN_ADMINISTRATIVE_UNITS_DICTIONARY: VnProvinceUnitItem[] = COMPACT_VN_ADMIN_SEED.map(
  (p) => ({
    code: p.c,
    name: p.n,
    region: p.r,
    aliases: buildProvinceAliases(p.n, p.a),
    ghnProvinceId: p.gp,
    ghtkProvinceName: p.gk,
    vtpProvinceId: p.vp,
    jtCityCode: p.jt,
    isCurrent34Province: p.c34,
    mergedIntoProvinceCode: p.mc,
    mergedIntoProvinceName: p.mn,
    mergedFromProvinceCodes: p.mfc,
    mergedFromProvinceNames: p.mfn,
    districts: p.d.map((d) => ({
      code: d.c,
      name: d.n,
      unitType: /^Quận\s+/i.test(d.n)
        ? 'QUAN'
        : /^Thành phố\s+/i.test(d.n)
          ? 'THANH_PHO'
          : /^Thị xã\s+/i.test(d.n)
            ? 'THI_XA'
            : /^(Đặc khu|Huyện đảo)\s+/i.test(d.n)
              ? 'DAC_KHU'
              : 'HUYEN',
      aliases: buildDistrictAliases(d.n),
      ghnDistrictId: d.g,
      ghtkDistrictName: d.n,
      wards: d.w.map((w) => ({
        code: w.c,
        name: w.n,
        unitType: /^Phường\s+/i.test(w.n)
          ? 'PHUONG'
          : /^Thị trấn\s+/i.test(w.n)
            ? 'THI_TRAN'
            : /^Đặc khu\s+/i.test(w.n)
              ? 'DAC_KHU'
              : 'XA',
        aliases: buildWardAliases(w.n, w.a),
        ghnWardCode: w.g,
        ghtkWardName: w.n,
        hamlets: buildFourthTierHamlets(w.c, w.n, p.r, w.a),
      })),
    })),
  }),
);

/**
 * Danh sách 34 Tỉnh/Thành phố hiện tại của Việt Nam (sau sáp nhập theo Nghị quyết 202/2025/QH15),
 * tự động hợp nhất toàn bộ 703 Quận/Huyện/Thị xã/TP thuộc tỉnh và 3.686 Phường/Xã/Thị trấn/Đặc khu
 * từ các tỉnh thành hợp nhất vào cây hành chính 3 cấp chính toàn quốc.
 */
export const VN_CURRENT_34_PROVINCES_DICTIONARY: VnProvinceUnitItem[] = (() => {
  const byMergedCode = new Map<string, VnProvinceUnitItem>();

  for (const prov of VN_ADMINISTRATIVE_UNITS_DICTIONARY) {
    const targetCode = prov.mergedIntoProvinceCode || prov.code;
    const existing = byMergedCode.get(targetCode);

    if (!existing) {
      byMergedCode.set(targetCode, {
        ...prov,
        code: targetCode,
        name: prov.mergedIntoProvinceName || prov.name,
        isCurrent34Province: true,
        aliases: [...prov.aliases],
        districts: [...prov.districts],
      });
    } else {
      const mergedAliases = Array.from(new Set([...existing.aliases, ...prov.aliases]));
      const mergedDistricts = [...existing.districts];
      const existingDistCodes = new Set(mergedDistricts.map((d) => d.code));
      for (const dist of prov.districts) {
        if (!existingDistCodes.has(dist.code)) {
          mergedDistricts.push(dist);
          existingDistCodes.add(dist.code);
        }
      }
      byMergedCode.set(targetCode, {
        ...existing,
        ...(prov.code === targetCode
          ? {
              ghnProvinceId: prov.ghnProvinceId,
              ghtkProvinceName: prov.ghtkProvinceName,
              vtpProvinceId: prov.vtpProvinceId,
              jtCityCode: prov.jtCityCode,
            }
          : {}),
        aliases: mergedAliases,
        districts: mergedDistricts,
      });
    }
  }

  return Array.from(byMergedCode.values());
})();

/**
 * Export đồng nhất cho cả Frontend (`@/constant/vn-administrative-units`) và Backend:
 */
export const VN_FULL_ADMINISTRATIVE_UNITS_TREE: VnProvinceUnitItem[] =
  VN_ADMINISTRATIVE_UNITS_DICTIONARY;

export const VN_CURRENT_34_ADMINISTRATIVE_UNITS_TREE: VnProvinceUnitItem[] =
  VN_CURRENT_34_PROVINCES_DICTIONARY;

export default VN_FULL_ADMINISTRATIVE_UNITS_TREE;
